import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzTimePickerModule } from 'ng-zorro-antd/time-picker';
import { HrmControl } from '../shared/hrm-control';
import { HrmSize, HrmStatus, toNzStatus } from './hrm-input';

const toNz = (s: HrmSize) => (s === 'sm' ? 'small' : s === 'lg' ? 'large' : 'default');

/** hrm-time-picker — CVA Date, bọc nz-time-picker. */
@Component({
  selector: 'hrm-time-picker',
  imports: [FormsModule, NzTimePickerModule],
  template: `
    <nz-time-picker
      style="width:100%"
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      [nzFormat]="format()"
      [nzUse12Hours]="use12Hours()"
      [nzMinuteStep]="minuteStep()"
      [nzPlaceHolder]="placeholder()"
      [nzDisabled]="disabled()"
      [nzSize]="toNz(size())"
      [nzStatus]="toNzStatus(status())"></nz-time-picker>
  `,
  host: { class: 'hrm-time-picker', '[class.hrm-status-success]': "status() === 'success'" },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmTimePicker), multi: true }],
})
export class HrmTimePicker extends HrmControl<Date> {
  readonly placeholder = input('');
  readonly format = input('HH:mm');
  /** hiển thị 12 giờ kèm AM/PM (dùng với format 'h:mm a'). Mặc định 24h. */
  readonly use12Hours = input(false);
  /** bước nhảy phút của danh sách chọn (VD 15 → 00, 15, 30, 45). */
  readonly minuteStep = input(1);
  readonly size = input<HrmSize>('md');
  readonly status = input<HrmStatus>('');
  protected readonly toNz = toNz;
  protected readonly toNzStatus = toNzStatus;
}
